 265| // nodeValidateModule wraps a nodeExpand module for validation, ensuring that
 266| // no expansion is attempted during evaluation, when count and for_each
 267| // expressions may not be known.
 268| type nodeValidateModule struct {
 269| 	nodeExpandModule
 270| }
 271| 
 272| var _ GraphNodeExecutable = (*nodeValidateModule)(nil)
 273| 
 274| // GraphNodeEvalable
 275| func (n *nodeValidateModule) Execute(globalCtx EvalContext, op walkOperation) (diags tfdiags.Diagnostics) {
 276| 	_, call := n.Addr.Call()
 277| 	expander := globalCtx.InstanceExpander()
 278| 
 279| 	if n.ModuleCall.IgnoreNestedDeprecations {
 280| 		globalCtx.Deprecations().SuppressModuleCallDeprecation(n.Addr)
 281| 	}
 282| 
 283| 	// Modules all evaluate to single instances during validation, only to
 284| 	// create a proper context within which to evaluate. All parent modules
 285| 	// will be a single instance, but still get our address in the expected
 286| 	// manner anyway to ensure they've been registered correctly.
 287| 	for _, module := range expander.ExpandModule(n.Addr.Parent(), false) {
 288| 		moduleCtx := evalContextForModuleInstance(globalCtx, module)
 289| 
 290| 		// Validate our for_each and count expressions at a basic level
 291| 		// We skip validation on known, because there will be unknown values before
 292| 		// a full expansion, presuming these errors will be caught in later steps
 293| 		switch {
 294| 		case n.ModuleCall.Count != nil:
 295| 			_, countDiags := evaluateCountExpressionValue(n.ModuleCall.Count, moduleCtx)
 296| 			diags = diags.Append(countDiags)
 297| 
 298| 		case n.ModuleCall.ForEach != nil:
 299| 			forEachDiags := newForEachEvaluator(n.ModuleCall.ForEach, moduleCtx, false).ValidateResourceValue()
 300| 			diags = diags.Append(forEachDiags)
 301| 		}
 302| 
 303| 		diags = diags.Append(validateDependsOn(moduleCtx, n.ModuleCall.DependsOn))
 304| 
 305| 		// now set our own mode to single
 306| 		expander.SetModuleSingle(module, call)
 307| 	}
 308| 
 309| 	if !diags.HasErrors() {
 310| 		return diags.Append(n.EvalPolicy(globalCtx, op))
 311| 	}
 312| 
 313| 	return diags
 314| }
