 316| // EvalPolicy evaluates the module policy.
 317| // Contrary to resource policy evaluation, module policy evaluation is done inline,
 318| // allowing us to block the evaluation of the module's resources within the graph if the policy fails.
 319| // Module policies have no support for callback functions, so we do not need to worry about
 320| // them retrieving objects that are not yet available in the state.
 321| func (n *nodeExpandModule) EvalPolicy(ctx EvalContext, op walkOperation) tfdiags.Diagnostics {
 322| 	if ctx.PolicyClient() == nil {
 323| 		log.Printf("[DEBUG] No policy client configured, skipping policy evaluation for %s", n.Addr)
 324| 		return nil
 325| 	}
 326| 
 327| 	configBundle := n.ModuleTree
 328| 	source := configBundle.SourceAddr.String()
 329| 
 330| 	// We will evaluate the module policy with just the metadata and not the module inputs.
 331| 	// Terraform modules act as namespace scopes and do not directly participate
 332| 	// in the reference flow in the graph.
 333| 	// This allows references in their inputs to be deferred until
 334| 	// they are used by a concrete object in the module.
 335| 	// Since policy evaluation is supposed to be done before evaluating the module's
 336| 	// objects, evaluating module inputs here would be incorrect as
 337| 	// it could lead to cyclic dependencies.
 338| 	// For example: Given the below module call,
 339| 	//
 340| 	// module "child" {
 341| 	// 	 source = "./child"
 342| 	// 	 input  = "child-value"
 343| 	// 	 input2 = module.child.output
 344| 	// }
 345| 	//
 346| 	// resource "test_instance" "test" {
 347| 	// 	 value = var.input
 348| 	// }
 349| 	// resource "test_instance" "test2" {
 350| 	// 	 value = var.input2
 351| 	// }
 352| 	// output "output" {
 353| 	// 	 value = resource.test_instance.test.value
 354| 	// }
 355| 	//
 356| 	// This is a valid terraform module call, but the input2 value depends on the module's output,
 357| 	// which is not available until after the module is expanded, and potentially resources have been created.
 358| 	// In the above example, the reference to `module.child.output` is deferred until the resource
 359| 	// `test_instance.test2` is evaluated, and any attempt to evaluate it here would result in a cyclic dependency error.
 360| 	result := ctx.PolicyClient().EvaluateModule(ctx.StopCtx(), policy.EvaluationRequest[*proto.PolicyEvaluateModuleRequest_ModuleMetadata]{
 361| 		Attrs:  policy.PolicyValue{Raw: cty.DynamicVal},
 362| 		Target: source,
 363| 		Meta: &proto.PolicyEvaluateModuleRequest_ModuleMetadata{
 364| 			Address: n.Addr.String(),
 365| 			Version: func() string {
 366| 				// local modules do not have versions, so we just return
 367| 				// an empty string in that case.
 368| 				if configBundle.Version == nil {
 369| 					return ""
 370| 				}
 371| 				return configBundle.Version.String()
 372| 			}(),
 373| 		},
 374| 	})
 375| 
 376| 	// add local range to diagnostics if the module call has a config body.
 377| 	if n.ModuleCall.Config != nil {
 378| 		ptr := n.ModuleCall.DeclRange.Ptr()
 379| 		for idx, diag := range result.Diagnostics {
 380| 			result.Diagnostics[idx] = diag.WithLocalRange(ptr)
 381| 		}
 382| 		for idx := range result.Enforcements {
 383| 			result.Enforcements[idx].LocalRange = ptr
 384| 		}
 385| 	}
 386| 
 387| 	// always add the result to the policy results
 388| 	if ctx.PolicyResults() != nil {
 389| 		ctx.PolicyResults().AddModule(n.Addr, result, n.ModuleCall)
 390| 	}

